  add('an-how', 'Nasıl çalışır?', { n: 'Analiz motorunun kısa açıklaması.', u: 'Ayrıntılar için Yöntem ve doğrulama sekmesine bak.', o: [], b: '—', w: '—', r: '—' });
  add('an-score', ['Skor', 'Neden bu skor?'], { n: 'Varlığın 0-100 analiz skoru ve alt skorların kanıtları.', u: 'Alt skorlar: trend, momentum, risk, değerleme, göreli güç, likidite. Artı/eksi katkılara bak. Helal durumu skora katılmaz, alım planı için kapıdır.', o: [['70+', 'Güçlü.'], ['50-70', 'Nötr / izlenebilir.'], ['<50', 'Zayıf.']], b: 'Yüksek skor + alım bölgesinde fiyat + yeterli güven.', w: 'Düşük güvenli (az veri) yüksek skora güvenmek.', r: 'Skor geçmişe bakar; ani haberde hızla değişebilir.' }, ['analiz']);
  add('an-plan', 'Alım planı', { n: 'Grafikteki yapıdan hesaplanan giriş bölgesi, stop ve hedefler (muhafazakâr / agresif).', u: 'Fiyat giriş bölgesindeyse ve R/Ö ≥ 1,5 ise plan uygulanabilir; değilse bölgeye uyarı kur.', o: [['Muhafazakâr', 'Daha güçlü destek, daha düşük risk.'], ['Agresif', 'Kırılım/yakın destek, daha erken giriş.'], ['R/Ö', 'Hedefe uzaklık / stopa uzaklık.']], b: 'Muhafazakâr plan, R/Ö ≥ 2, stopa sadık kalmak.', w: 'Stopu sürekli aşağı çekmek.', r: 'Boşluklu açılışta stop seviyesinden kötü fiyattan çıkılabilir.' });
  add('an-chart', ['Grafik', 'Grafik yapısı'], { n: 'Mum grafiği, destek/direnç bölgeleri, trend çizgileri ve göstergeler.', u: 'İki parmakla yakınlaştır, sürükle. Yeşil = destek, kırmızı = direnç, kesikli = trend/kanal. Alt panelden gösterge seç.', o: [['Aralık', '3A / 6A / 1Y / Tümü.'], ['Katmanlar', 'Ortalama, Bollinger, formasyon.']], b: 'Bölgeleri plan seviyeleriyle birlikte okumak.', w: 'Tek bir göstergeye göre karar.', r: 'Formasyonlar olasılıktır, kesinlik değil.' });
  add('an-fund', ['Temel analiz', /^Fon analizi/, 'Kripto piyasa göstergeleri'], { n: 'Hissede F/K, PD/DD, kârlılık, borç; fonda getiri, büyüklük, risk, içerik; kripto piyasa göstergeleri.', u: 'Benzerleriyle kıyasla; değerleme alt skoruna katkısını gör.', o: [], b: 'Kârlı, düşük borçlu, makul değerli şirket; fonda istikrarlı getiri ve yeterli büyüklük.', w: 'Yalnız düşük F/K\'ya bakmak (değer tuzağı).', r: 'Temel veri gecikmeli (çeyreklik) olabilir.' });
  add('an-verify', ['Doğrulama', 'Gösterge doğrulaması', 'Veri kaynakları', 'Kurallar', 'Skor ağırlıkları', 'Araçlar ve gerekçeleri'], { n: 'Verilerin ve göstergelerin nasıl doğrulandığı, kaynaklar, ağırlıklar ve kurallar.', u: '"Testi çalıştır" ile göstergeleri tarayıcında TA-Lib referansıyla yeniden doğrula.', o: [], b: 'Kararlarından önce kaynak ve saatine bakmak.', w: 'Kaynağı belirsiz veriye güvenmek.', r: 'Ücretsiz kaynaklar resmî değildir; kesintiler olabilir.' });
  add('an-news', ['Haberler'], { n: 'Varlıkla/piyasayla ilgili son haber başlıkları ve duygu etiketi.', u: 'Başlığa dokunup haberi kaynağında oku.', o: [], b: 'Haberi okuyup planı gözden geçirmek.', w: 'Başlığa göre panik alım/satım.', r: 'Duygu etiketi basit kelime eşleştirmesidir; yanılabilir.' }, ['analiz', 'ozet']);
  add('an-ohlcv', 'Kendi verini yükle', { n: 'Kaynağı olmayan bir varlık için OHLCV verisini yapıştırarak analiz.', u: 'Tarih, Açılış, En yüksek, En düşük, Kapanış, Hacim sütunlarını yapıştır (yalnız Tarih+Kapanış da olur).', o: [], b: 'En az 1 yıllık günlük veri.', w: 'Az veri (skor güvenilmez).', r: 'Veri doğruluğu senin sorumluluğundadır.' });
  add('an-oldbuild', ['Profilin', 'Önerilen dağılım', 'Geçmiş test'], { n: 'Dağılım ve geçmiş test bölümleri.', u: 'Geçmiş test önerilen karışımı son 3 yılın fiyatlarıyla (aylık dengeleme) dener.', o: [], b: 'En kötü 12 ay rakamına bakarak "buna dayanabilir miyim?" diye sormak.', w: 'Yalnız yıllık getiriye bakmak.', r: 'Geçmiş, geleceğin garantisi değildir.' });
  /* ================= PORTFÖY OLUŞTURUCU (v8.8) ================= */
  E['page:analiz/olustur'] = { n: 'Filtrelerine ve yatırımcı profiline göre, gerçek fiyat verisiyle yeni bir portföy oluşturur. Tutar yazarsan oluşturma anındaki fiyatlardan sanal alım yapar ("almış gibi"). Bu portföy gerçek varlıklarından, alım-satımlarından ve bütçenden tamamen ayrıdır.', u: '1) İstersen tutar (TL) ve ad yaz. 2) Profil seç (ya da "Standart filtreye dön"). 3) Filtreleri ayarla; çelişki varsa kırmızı/sarı uyarı çıkar. 4) "Portföyü oluştur" → rapor. 5) Beğendiysen "Kaydet ve takibe al" → Kayıtlı portföylerim.', o: [['Tutar boş', 'Yüzde ağırlıklı model portföy (adet yok).'], ['Tutar dolu', 'Sanal alım: adet, maliyet, tarih; bölgede olmayanlar bekleyen emir.']], b: 'Tutar yazıp Dengeli (standart) profil, helal filtresi açık, "alım bölgesindekileri tercih et" açık.', w: 'Helal filtresini kapatıp agresif + kısa vade seçmek.', r: 'Sanal portföy gerçek emir göndermez; seviyeler olasılıktır. Yatırım tavsiyesi değildir.' };
  add('lab-amt', 'Portföy tutarı ve adı', { n: 'Portföyün büyüklüğü (isteğe bağlı) ve adı.', u: 'Tutarı TL olarak yaz (en az 1.000 TL) ya da boş bırak. Ad boşsa tarihli bir ad verilir.', o: [['Boş tutar', 'Yalnız yüzde ağırlıklar; takipte "oluşturmadan beri getiri" gösterilir.'], ['Tutar', 'Her varlığa düşen TL, adet (lot adımına göre aşağı yuvarlanır), artan nakit ve bekleyen emir tutarı hesaplanır.']], b: 'Gerçekten yatırmayı düşündüğün tutar: takipte K/Z TL olarak anlamlı olur.', w: 'Çok küçük tutar: tam lotlu hisselerde yuvarlama payı büyür, nakit artar.', r: 'Sanal alım komisyon ve kayma (slippage) içermez; gerçek alım biraz daha pahalı olabilir.' });
  add('lab-filters', 'Filtreler ve yatırımcı profili', { n: 'Portföyün hangi araçlardan, hangi risk ve vadeyle kurulacağını belirler. Profil seçince filtreler otomatik ayarlanır; sonra istediğini değiştirebilirsin (profil "Özel" olur).', u: 'Önce profil seç, sonra gerekirse tek tek değiştir. "Standart filtreye dön" her şeyi Dengeli + helal açık hâline getirir. Seçimlerin bu cihazda hatırlanır.', o: [
    ['Muhafazakâr', 'Düşük risk, orta vade, 6 varlık, tek varlık ≤ %30, en düşük skor 50, yalnız yüksek likidite, Döviz açık. Ağırlık güvenli/orta gruplarda.'],
    ['Dengeli (standart)', 'Orta risk, orta vade, 8 varlık, ≤ %25, skor ≥ 45, orta+ likidite, dolar bazlı helal ETF açık.'],
    ['Agresif (büyüme)', 'Yüksek risk, uzun vade, 10 varlık, ≤ %20, skor ≥ 45. Ağırlık hisse/ETF\'te.'],
    ['Helal filtresi (varsayılan AÇIK)', 'Açıkken yalnız helal etiketi "uygun" olan araçlar (Katılım endeksi hisseleri, İslami/katılım fonları, fiziki altın/gümüş, şer\'i endeks ETF\'leri) seçilir; kripto dışarıda kalır. Kapalıyken BIST 100 hisseleri de aday olur ve uyarı gösterilir; "uygun değil" etiketliler yine de hiçbir zaman eklenmez. Fonlar her durumda yalnız katılım fonlarıdır.'],
    ['Vade', 'Kısa (< 2 yıl): ağırlık güvenli grupta. Orta (2-5 yıl). Uzun (5+ yıl): riskli grup payı yüksek olabilir.'],
    ['Risk', 'Düşük / orta / yüksek: güvenli-orta-riskli grup paylarını ve oynaklık sınırını belirler (vade × risk tablosu Yöntem sekmesinde).'],
    ['Varlık sınıfları', 'BIST hissesi, TEFAS fonu, altın/gümüş, kripto. Kapattığın sınıf hiç seçilmez.'],
    ['Döviz', 'Dolar/euro (TL karşılığı) ekler; orta risk grubunda yer alır.'],
    ['Dolar bazlı helal ETF dahil', 'HLAL, SPUS, SPSK, SPRE, SPTE, SPWO, UMMA gibi şer\'i endeks ETF\'leri ekler (USD, ABD borsası).'],
    ['Yalnız TL araçlar', 'Tabanı TL araçlarla (BIST, TEFAS, gram altın TL) sınırlar ve kriptoyu çıkarır. Döviz ve/veya ETF kutusu da işaretliyse bunlar BİLEREK eklenen istisnalardır: üçü birlikte seçilebilir, birbirini kapatmaz; döviz cinsi toplam pay en fazla %30 tutulur ve bilgi notu gösterilir.'],
    ['Varlık sayısı', 'Hedef varlık sayısı (3-15). Tek varlık sınırıyla %100 dolmuyorsa sayı otomatik artırılır ve not düşülür.'],
    ['Tek varlık üst sınırı', 'Bir varlığın alabileceği en yüksek pay. Fazlası aynı veya daha düşük riskli gruba, o da olmazsa nakde aktarılır (risk asla artırılmaz).'],
    ['En düşük analiz skoru', 'Bu skorun altındaki varlıklar aday olmaz. Yükseltmek kaliteyi artırır ama aday sayısını azaltır.'],
    ['Likidite', 'Hepsi / orta ve üstü / yalnız yüksek: işlem hacmine göre (likidite alt skoru). Düşük likidite = alırken/satarken fiyat kayması.'],
    ['Hemen alınabilir pay hedefi', 'Portföyün en az bu kadarı şu an alım bölgesinde olan varlıklardan oluşsun diye bekleyen varlıklar bölgede olanlarla değiştirilir (skor farkı çok büyük değilse).'],
    ['Alım bölgesindekileri tercih et', 'Sıralamada alım bölgesindeki varlıklara artı puan verir; böylece portföyün tamamı beklemede kalmaz.'],
    ['Sektör', 'Yalnız seçtiğin BIST sektörlerinden hisse (boş = hepsi). Aynı sektörden en fazla 2 hisse alınır.']], b: 'Standart (Dengeli) + helal açık + alım bölgesi tercihi açık + hemen alınabilir pay %50; uzun vadeli birikim için.', w: 'Kısa vade + yüksek risk, ya da tek varlık sınırı %50 + 3 varlık (aşırı yoğunlaşma).', r: 'Çelişkili seçimlerde uyarı çıkar ve sessizce yok sayılmaz: ör. helal açık + kripto (kripto çıkarılır), Yalnız TL + kripto (kripto çıkarılır), hiç sınıf seçmemek (oluşturulamaz), varlık sayısı × üst sınır < %100 (sayı artırılır), düşük risk ama fon/altın/döviz kapalı (yüksek oynaklık).' });
  add('lab-result', [/^Oluşturulan portföy/], { n: 'Oluşturulan portföyün henüz kaydedilmemiş önizlemesi.', u: 'Raporu incele; adı değiştirip "Kaydet ve takibe al"a bas ya da "Vazgeç". Kaydedilmeyen sonuç sayfadan çıkınca kaybolur.', o: [['Kaydet ve takibe al', 'Kayıtlı portföylerim\'e ekler; sanal alım fiyatları ve tarih saklanır.'], ['Vazgeç', 'Sonucu siler.']], b: 'Kaydetmeden önce uyarılar ve "Varlıklar" kartlarını okumak.', w: 'Uyarı kartını okumadan kaydetmek.', r: 'Fiyatlar oluşturma anına aittir; kaydı geciktirirsen değişmiş olabilir.' });
  E['lab-report'] = { n: 'Portföyün başlığı: analiz skoru (0-100), tutar, güncel değer, kâr/zarar, bekleyen nakit ve skor bileşenleri.', u: 'Skorun altındaki çubuklar bileşenlerdir; "Skor nasıl hesaplandı?" kanıtları gösterir.', o: [['Kalite (35)', 'Varlık skorlarının ağırlıklı ortalaması.'], ['Çeşitlendirme (20)', 'Etkin varlık sayısı (korelasyonla).'], ['Risk uyumu (15)', 'Yıllık oynaklık / profil sınırı.'], ['Düşüş (10)', 'Son 1 yılın en büyük düşüşü / profil sınırı.'], ['Zamanlama (10)', 'Hemen alınabilir pay ve ortalama R/Ö.'], ['Likidite (5)', 'Ağırlıklı likidite.'], ['Helal (5)', 'Uygun etiketli pay.']], b: '70+ (B ve üstü) ve kapsamı tam skor.', w: '"Veri yetersiz" olduğu hâlde karar vermek.', r: 'Hesaplanamayan bileşenin ağırlığı diğerlerine dağıtılır; kapsam %50\'nin altındaysa skor verilmez — uydurulmaz.' };
  add('lab-warn', 'Uyarılar ve öneriler', { n: 'Stop/hedef olayları, bekleyen emrin seviyesine gelen fiyat, helal uyarıları, yeniden dengeleme önerileri ve kurulum notları.', u: 'Kırmızı = stop görüldü (planı gözden geçir); yeşil = hedef/alım seviyesi; sarı = dikkat. Yeniden dengelemede önce yeni parayla geride kalanı tamamla.', o: [['Yeniden dengeleme', 'Hedef paydan ≥ 5 puan sapan varlıklar.']], b: 'Uyarıları düzenli okuyup planı güncellemek.', w: 'Stop uyarısını görmezden gelmek.', r: 'Olaylar günlük mumlarla bulunur; gün içi dokunuşlar gecikmeli görünebilir.' });
  add('lab-dist', 'Dağılım', { n: 'Varlıkların ve nakdin pay dağılımı; güvenli/orta/riskli grup payları.', u: 'Dilime dokununca pay görünür.', o: [], b: 'Profilinin grup paylarına yakın dağılım.', w: 'Nakit payının çok büyük olması (yeterli aday yok → filtreleri gevşet).', r: '—' }, ['analiz']);
  add('lab-scores', 'Varlık skorları', { n: 'Her varlığın 0-100 analiz skoru.', u: 'Çubuk rengi: yeşil güçlü, sarı orta, kırmızı zayıf. Skor yoksa "veri yetersiz".', o: [], b: 'Tüm varlıklar 50+.', w: 'Düşük skorlu varlığa büyük pay.', r: 'Skor geçmiş fiyat yapısına dayanır.' });
  add('lab-rr', 'Risk / getiri', { n: 'Her varlığın yıllık oynaklığı (yatay) ve son 1 yıl getirisi (dikey); nokta büyüklüğü pay.', u: 'Sol üst = düşük risk, yüksek getiri (iyi); sağ alt = yüksek risk, düşük getiri (kötü).', o: [], b: 'Büyük noktaların sol/üst bölgede olması.', w: 'Büyük noktaların sağ altta olması.', r: 'Geçmiş getiri geleceği garanti etmez.' });
  add('lab-hist', 'Değer takibi', { n: 'Portföyün zaman içindeki değeri (her güncellemede günde bir nokta).', u: 'Detay sayfasını açtıkça veya "Güncelle"ye bastıkça nokta eklenir.', o: [], b: 'Düzenli (haftalık) güncelleme.', w: '—', r: 'Güncelleme yapılmayan günler grafikte boş kalır.' });
  add('lab-risk', 'Beklenen risk', { n: 'Portföyün beklenen yıllık oynaklığı, 1 aylık %95 riske maruz değer (VaR), son 1 yılın ve 3 yıllık testin en büyük düşüşü, olası en büyük düşüş tahmini ve korelasyon.', u: 'VaR: normal koşullarda 20 ayda 1 bundan kötü bir ay beklenir. Olası en büyük düşüş = geçmiş en büyük düşüş ile 2σ\'nın büyüğü.', o: [['Korelasyon', '1\'e yakın = birlikte hareket (çeşitlendirme zayıf).']], b: 'Oynaklık profil sınırının altında, olası düşüşü taşıyabileceğin seviyede.', w: 'Olası düşüşü kaldıramayacağın bir portföy.', r: 'Kriz dönemlerinde korelasyonlar artar; gerçek düşüş tahmini aşabilir.' });
  add('lab-assets', 'Varlıklar: alım, hedef ve stop seviyeleri', { n: 'Her varlığın skoru, durumu, alım bölgesi, stop, hedef 1/2, risk/ödül, sanal alım (adet, maliyet, tarih) ve kâr/zararı.', u: 'Durum: "Şimdi alınabilir" (bölgede ve R/Ö ≥ 1,5), "Bekle — şu seviyeye gelirse al" (bekleyen emir), "İz süren stop" (güçlü trend, desteğin üstünde: fiyat − 2,5×ATR stop), "Yapı bozuldu". Seviye cetvelinde mavi şerit = alım bölgesi, kırmızı = stop, yeşil = hedefler, kesikli = bekleyen emir, siyah nokta = güncel fiyat.', o: [['Alım bölgesi', 'Destek bölgesi veya kırılan direncin geri testi (en az 2 dokunuşlu pivot kümesi).'], ['Stop', 'Yapısal dip − ATR tamponu.'], ['Hedefler', 'Sonraki direnç bölgeleri / Fibonacci uzantıları.'], ['Bekleyen emir', 'Fiyat seviyeye inince ilk günlük mumda dolmuş sayılır.']], b: 'Bölgedekileri hemen, bekleyenleri limit emirle almak; stopa sadık kalmak.', w: 'Stop altına inen varlıkta beklemeye devam etmek.', r: 'Boşluklu açılış stopu atlayabilir; düşük likiditede emir dolmayabilir.' });
  add('lab-table', 'Özet tablo', { n: 'Tüm varlıkların seviyeleri ve K/Z\'si tek tabloda.', u: 'Telefonda satırlar kart olarak alt alta görünür.', o: [], b: '—', w: '—', r: '—' });
  E['page:analiz/portfoylerim'] = { n: 'Kaydettiğin sanal portföyler: her biri ayrı takip edilir (K/Z, skor, bekleyen emirler).', u: 'Bir portföye dokun → canlı fiyatlarla yeniden analiz edilir. Yeniden adlandır, sil, karşılaştır.', o: [['Aç ve analiz et', 'Detay ve rapor.'], ['Tümünü güncelle', 'Hepsinin değerini canlı fiyatla yeniler.'], ['Karşılaştır', 'Seçtiğin portföyleri tabloda kıyaslar.'], ['Sil', 'Yalnız sanal portföy silinir; "Geri al" ile geri gelir.']], b: 'Haftada bir güncelleyip uyarıları okumak.', w: 'Sanal K/Z\'yi gerçek kazanç sanmak.', r: 'Sanal alım komisyon/vergi içermez.' };
  add('lab-list', ['Kayıtlı portföylerim', 'Portföy karşılaştırma'], E['page:analiz/portfoylerim'], ['analiz']);
  E['lab-actions'] = { n: 'Bu portföy üzerindeki işlemler.', u: '"Güncelle ve yeniden analiz et" tüm varlıkları canlı fiyatla tekrar analiz eder, bekleyen emirlerin dolup dolmadığını ve stop/hedef olaylarını kontrol eder.', o: [['Bekleyen emirleri taşı', 'Bekleyen emir seviyesini güncel alım bölgesine taşır.'], ['Gerçek portföyüme hedef olarak uygula', 'İstersen yalnız helal uygun hisse/fon/altın/ETF\'leri gerçek portföyünün hedef dağılımına yazar (işlem eklenmez, önce yedek alınır).'], ['Yazdır / PDF', 'Raporu yazdırır.']], b: 'Önce güncelle, sonra karar ver.', w: '"Uygula"yı denemek için kullanmak (gerçek hedeflerini değiştirir).', r: 'Uygula, gerçek portföyündeki grup içi hedefleri değiştirir.' };
  /* ================= HABERLER (MERKEZ) ================= */
  page('haberler', { n: 'Piyasa nabzı, haberler, takvim, olay senaryoları, bildirim ayarları ve arka plan işleri.', u: 'Sekmeler arasında gez; bildirim eşiklerini ve sessiz saatleri ayarla.', o: [], b: 'Önemli olaylar için bildirim, geri kalanı için günlük özet.', w: 'Her habere bildirim açmak.', r: 'Haber kaynakları gecikebilir; duygu etiketi basit kelime eşleştirmesidir.' });
  add('hb-load', 'Veri yükleniyor', { n: 'Merkez verisi sunucudan yükleniyor.', u: 'Birkaç saniye bekle; olmazsa sayfayı yenile.', o: [], b: '—', w: '—', r: 'Bağlantı yoksa son bilinen veri gösterilir.' });
